// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PhiNFT1155} from "../src/PhiNFT1155.sol";

contract InvMutTest is Test {
    PhiNFT1155 c;
    function setUp() public { c = new PhiNFT1155(); }
    function testFuzz_property(address caller1, address caller2) public {
        vm.assume(caller1 != caller2);
        vm.assume(caller1 != address(0));
        vm.assume(caller2 != address(0));
        vm.assume(caller1 != address(this));
        vm.assume(caller2 != address(this));

        vm.prank(caller1);
        address ownerCaller1 = c.owner();

        vm.prank(caller2);
        address ownerCaller2 = c.owner();

        assertTrue(ownerCaller1 == ownerCaller2);
    }
}
